/// <summary>
/// Returns a human-readable string representation using the largest whole number unit.
/// </summary>
public override string ToString()
{
    GetLargestWholeNumber(out double value, out string symbol);
    return string.Create(CultureInfo.CurrentCulture, $"{value:0.##} {symbol}");
}

/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    if (string.IsNullOrEmpty(format))
    {
        GetLargestWholeNumber(out double val, out string sym);
        return $"{val.ToString("0.##", formatProvider ?? CultureInfo.CurrentCulture)} {sym}";
    }

    formatProvider ??= CultureInfo.CurrentCulture;

    // Determine which unit the format string requests
    if (ContainsUnit(format, TerabyteSymbol, out var numericFormat))
        return FormatValue(Terabytes, numericFormat, TerabyteSymbol, formatProvider);
    if (ContainsUnit(format, GigabyteSymbol, out numericFormat))
        return FormatValue(Gigabytes, numericFormat, GigabyteSymbol, formatProvider);
    if (ContainsUnit(format, MegabyteSymbol, out numericFormat))
        return FormatValue(Megabytes, numericFormat, MegabyteSymbol, formatProvider);
    if (ContainsUnit(format, KilobyteSymbol, out numericFormat))
        return FormatValue(Kilobytes, numericFormat, KilobyteSymbol, formatProvider);
    if (ContainsUnit(format, ByteSymbol, out numericFormat))
        return FormatValue(_bytes, numericFormat, ByteSymbol, formatProvider);
    if (ContainsUnit(format, BitSymbol, out numericFormat))
        return FormatValue(Bits, numericFormat, BitSymbol, formatProvider);

    // No unit in format string — use largest whole number unit
    GetLargestWholeNumber(out double value, out string symbol);
    return $"{value.ToString(format, formatProvider)} {symbol}";
}

private static bool ContainsUnit(string format, string unit, out string numericFormat)
{
    int idx = format.IndexOf(unit, StringComparison.OrdinalIgnoreCase);
    if (idx >= 0)
    {
        numericFormat = string.Concat(format.AsSpan(0, idx), format.AsSpan(idx + unit.Length)).Trim();
        if (numericFormat.Length == 0) numericFormat = "0.##";
        return true;
    }
    numericFormat = "";
    return false;
}

private static string FormatValue(double value, string numericFormat, string unit, IFormatProvider provider)
{
    return $"{value.ToString(numericFormat, provider)} {unit}";
}

